insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a2-06','en-a2-06',null,2,6,'published',1,'{"id":"en-a2-06","baseId":"en-a2-06","revision":1,"level":"A2","levelIndex":2,"order":6,"title":"Taqqoslash va eng yuqori daraja","objective":"Ikki yoki ko‘p variantni comparative/superlative bilan solishtirasiz.","context":"O‘quvchilar klub uchun qaysi xona qulayligini tanlaydi.","prerequisites":["en-a2-05"],"minutes":40,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Qisqa sifatlarda -er va the -est: small → smaller → the smallest. Happy → happier, big → bigger.","Uzunroq sifatlarda more/the most: more comfortable. Good → better → the best, bad → worse → the worst.","Ikki narsani than bilan taqqoslaymiz. Guruh ichida the tallest in the class kabi ibora ishlatiladi. More better shakli ikki marta taqqoslashdir."],"pattern":"smaller than / more comfortable than / the best in …","examples":["Room 2 is smaller than Room 5.","This chair is more comfortable.","Lola is taller than Ali.","This is the best place to study.","The library is the quietest room.","My bag is heavier than yours."],"vocabulary":[{"id":"en-a2-06-v0","term":"comfortable","meaning":"qulay","ipa":"/ˈkʌmftəbəl/","collocation":"a comfortable chair","example":"This chair is more comfortable."},{"id":"en-a2-06-v1","term":"quiet","meaning":"sokin","ipa":"/ˈkwaɪət/","collocation":"the quietest room","example":"The library is the quietest room."},{"id":"en-a2-06-v2","term":"heavy","meaning":"og‘ir","ipa":"/ˈhevi/","collocation":"a heavier bag","example":"a heavier bag"},{"id":"en-a2-06-v3","term":"choose","meaning":"tanlamoq","ipa":"/tʃuːz/","collocation":"choose the best room","example":"We choose Room 5 for Friday meetings because it is large enough for twelve students."}],"visuals":[{"kind":"compare","title":"Ma’no va tuzilish","items":["smaller than / more comfortable than / the best in …","Room 2 is smaller than Room 5.","This chair is more comfortable."]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["O‘quvchilar klub uchun qaysi xona qulayligini tanlaydi.","Lola is taller than Ali.","The library is the quietest room."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"This is the best place to study.","audio":"/english-course/v7.23/en-a2-06-dictation.mp3"},"exercises":[{"id":"en-a2-06-choice","type":"choice","skill":"grammar","prompt":"Good ning eng yuqori shakli?","answers":["the best"],"explanation":"Good → better → the best.","hint":"smaller than / more comfortable than / the best in …","options":["the best","the goodest","the most good"]},{"id":"en-a2-06-gap","type":"grammarFill","skill":"grammar","prompt":"This room is ___ than that one. (small)","answers":["smaller"],"explanation":"Qisqa sifatlarda -er va the -est: small → smaller → the smallest. Happy → happier, big → bigger. Uzunroq sifatlarda more/the most: more comfortable. Good → better → the best, bad → worse → the worst. Ikki narsani than bilan taqqoslaymiz. Guruh ichida the tallest in the class kabi ibora ishlatiladi. More better shakli ikki marta taqqoslashdir.","hint":"smaller than / more comfortable than / the best in …"},{"id":"en-a2-06-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["Room 2 is smaller than Room 5."],"explanation":"Qisqa sifatlarda -er va the -est: small → smaller → the smallest. Happy → happier, big → bigger. Uzunroq sifatlarda more/the most: more comfortable. Good → better → the best, bad → worse → the worst. Ikki narsani than bilan taqqoslaymiz. Guruh ichida the tallest in the class kabi ibora ishlatiladi. More better shakli ikki marta taqqoslashdir.","hint":"smaller than / more comfortable than / the best in …","tokens":["Room","2","is","smaller","than","Room","5."]},{"id":"en-a2-06-fix","type":"correction","skill":"grammar","prompt":"This is more better.","answers":["This is better."],"explanation":"Qisqa sifatlarda -er va the -est: small → smaller → the smallest. Happy → happier, big → bigger. Uzunroq sifatlarda more/the most: more comfortable. Good → better → the best, bad → worse → the worst. Ikki narsani than bilan taqqoslaymiz. Guruh ichida the tallest in the class kabi ibora ishlatiladi. More better shakli ikki marta taqqoslashdir.","hint":"smaller than / more comfortable than / the best in …"},{"id":"en-a2-06-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["qulay","sokin","og‘ir","tanlamoq"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"smaller than / more comfortable than / the best in …","left":["comfortable","quiet","heavy","choose"],"options":["qulay","sokin","og‘ir","tanlamoq"]},{"id":"en-a2-06-collocations","type":"collocation","skill":"vocabulary","prompt":"So‘zlarni darsdagi birikmasi bilan moslang.","left":["comfortable","quiet","heavy","choose"],"options":["a comfortable chair","the quietest room","a heavier bag","choose the best room"],"answers":["a comfortable chair","the quietest room","a heavier bag","choose the best room"],"hint":"So‘z qaysi birikmada ishlatilishini eslang.","explanation":"Birikmani yozgan gapingizda ham ishlating."}],"reading":{"title":"Taqqoslash va eng yuqori daraja — vaziyat","text":"We need a room for our reading club. Room 2 is smaller than Room 5, but it has more comfortable chairs. Room 5 is brighter because it has three windows. The library is the quietest place in the school, but it closes early. We choose Room 5 for Friday meetings because it is large enough for twelve students. It isn’t the quietest room, so we agree to speak softly. For individual reading, we think the library is still the best choice.","sentences":["We need a room for our reading club.","Room 2 is smaller than Room 5, but it has more comfortable chairs.","Room 5 is brighter because it has three windows.","The library is the quietest place in the school, but it closes early.","We choose Room 5 for Friday meetings because it is large enough for twelve students.","It isn’t the quietest room, so we agree to speak softly.","For individual reading, we think the library is still the best choice."],"questions":[{"id":"en-a2-06-reading0","type":"choice","skill":"reading","prompt":"Nega Room 5 tanlandi?","answers":["it is large enough"],"explanation":"Large enough for twelve students.","hint":"smaller than / more comfortable than / the best in …","options":["it is large enough","it has the best chairs","it is the smallest"]},{"id":"en-a2-06-reading1","type":"choice","skill":"reading","prompt":"Eng sokin joy qaysi?","answers":["the library"],"explanation":"The library is the quietest.","hint":"smaller than / more comfortable than / the best in …","options":["the library","Room 5","Room 2"]},{"id":"en-a2-06-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"smaller than / more comfortable than / the best in …","options":["We need a room for our reading club.","Room 2 is smaller than Room 5, but it has more comfortable chairs.","Room 5 is brighter because it has three windows.","The library is the quietest place in the school, but it closes early.","We choose Room 5 for Friday meetings because it is large enough for twelve students.","It isn’t the quietest room, so we agree to speak softly.","For individual reading, we think the library is still the best choice."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"Room 2 is smaller than Room 5. Room 5 is brighter, but Room 2 has more comfortable chairs. The library is the quietest place. We choose Room 5 because it has enough space.","audio":"/english-course/v7.23/en-a2-06.mp3","synthetic":true,"questions":[{"id":"en-a2-06-listening0","type":"choice","skill":"listening","prompt":"Qaysi xona yorug‘roq?","answers":["Room 5"],"explanation":"Room 5 is brighter.","hint":"smaller than / more comfortable than / the best in …","options":["Room 5","Room 2","Room 1"]},{"id":"en-a2-06-listening1","type":"choice","skill":"listening","prompt":"Qayerdagi stullar qulayroq?","answers":["Room 2"],"explanation":"Room 2 has more comfortable chairs.","hint":"smaller than / more comfortable than / the best in …","options":["Room 2","Room 5","outside"]},{"id":"en-a2-06-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["5","library"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"smaller than / more comfortable than / the best in …","rows":["Yorug‘roq xona","Eng sokin joy"]},{"id":"en-a2-06-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["This is the best place to study."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"smaller than / more comfortable than / the best in …","audio":"/english-course/v7.23/en-a2-06-dictation.mp3","transcript":"This is the best place to study."}]},"writing":{"task":"Ikki o‘qish joyini taqqoslang va eng mosini sabab bilan tanlang.","audience":"Sinfdagi sherigingiz","minWords":52,"maxWords":140,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"Our library is quieter than the café. It also has more books. The café is warmer and has more comfortable chairs, but it can be busy. For homework, I think the library is the best place because I can concentrate. For talking with friends after school, the café is a better choice.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["Room 2 is smaller than Room 5.","This chair is more comfortable.","Lola is taller than Ali."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Ikki xona rasmini taqqoslab birini klub uchun tanlang.","seconds":50,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Ikki o‘qish joyini taqqoslang va eng mosini sabab bilan tanlang.","exit":[[{"id":"en-a2-06-exit0","type":"grammarFill","skill":"grammar","prompt":"Tall ning comparative shakli?","answers":["taller"],"explanation":"Qisqa sifatlarda -er va the -est: small → smaller → the smallest. Happy → happier, big → bigger. Uzunroq sifatlarda more/the most: more comfortable. Good → better → the best, bad → worse → the worst. Ikki narsani than bilan taqqoslaymiz. Guruh ichida the tallest in the class kabi ibora ishlatiladi. More better shakli ikki marta taqqoslashdir.","hint":"smaller than / more comfortable than / the best in …"},{"id":"en-a2-06-exit1","type":"grammarFill","skill":"grammar","prompt":"Happy ning comparative shakli?","answers":["happier"],"explanation":"Qisqa sifatlarda -er va the -est: small → smaller → the smallest. Happy → happier, big → bigger. Uzunroq sifatlarda more/the most: more comfortable. Good → better → the best, bad → worse → the worst. Ikki narsani than bilan taqqoslaymiz. Guruh ichida the tallest in the class kabi ibora ishlatiladi. More better shakli ikki marta taqqoslashdir.","hint":"smaller than / more comfortable than / the best in …"},{"id":"en-a2-06-exit2","type":"grammarFill","skill":"grammar","prompt":"Good ning comparative shakli?","answers":["better"],"explanation":"Qisqa sifatlarda -er va the -est: small → smaller → the smallest. Happy → happier, big → bigger. Uzunroq sifatlarda more/the most: more comfortable. Good → better → the best, bad → worse → the worst. Ikki narsani than bilan taqqoslaymiz. Guruh ichida the tallest in the class kabi ibora ishlatiladi. More better shakli ikki marta taqqoslashdir.","hint":"smaller than / more comfortable than / the best in …"},{"id":"en-a2-06-exit3","type":"choice","skill":"grammar","prompt":"To‘g‘ri taqqoslashni tanlang.","answers":["quieter than"],"explanation":"Bir marta comparative yasaladi.","hint":"smaller than / more comfortable than / the best in …","options":["quieter than","more quieter than","quiet than"]},{"id":"en-a2-06-exit4","type":"choice","skill":"grammar","prompt":"Uzun sifatga mos shakl?","answers":["more comfortable"],"explanation":"Comparative more comfortable.","hint":"smaller than / more comfortable than / the best in …","options":["more comfortable","comfortabler","most comfortable than"]}],[{"id":"en-a2-06-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["This chair is more comfortable."],"explanation":"Qisqa sifatlarda -er va the -est: small → smaller → the smallest. Happy → happier, big → bigger. Uzunroq sifatlarda more/the most: more comfortable. Good → better → the best, bad → worse → the worst. Ikki narsani than bilan taqqoslaymiz. Guruh ichida the tallest in the class kabi ibora ishlatiladi. More better shakli ikki marta taqqoslashdir.","hint":"smaller than / more comfortable than / the best in …","tokens":["This","chair","is","more","comfortable."]},{"id":"en-a2-06-exit-b1","type":"grammarFill","skill":"grammar","prompt":"Happy ning comparative shakli?","answers":["happier"],"explanation":"Qisqa sifatlarda -er va the -est: small → smaller → the smallest. Happy → happier, big → bigger. Uzunroq sifatlarda more/the most: more comfortable. Good → better → the best, bad → worse → the worst. Ikki narsani than bilan taqqoslaymiz. Guruh ichida the tallest in the class kabi ibora ishlatiladi. More better shakli ikki marta taqqoslashdir.","hint":"smaller than / more comfortable than / the best in …"},{"id":"en-a2-06-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["This is the best place to study."],"explanation":"Qisqa sifatlarda -er va the -est: small → smaller → the smallest. Happy → happier, big → bigger. Uzunroq sifatlarda more/the most: more comfortable. Good → better → the best, bad → worse → the worst. Ikki narsani than bilan taqqoslaymiz. Guruh ichida the tallest in the class kabi ibora ishlatiladi. More better shakli ikki marta taqqoslashdir.","hint":"smaller than / more comfortable than / the best in …","tokens":["This","is","the","best","place","to","study."]},{"id":"en-a2-06-exit-b3","type":"choice","skill":"grammar","prompt":"To‘g‘ri taqqoslashni tanlang.","answers":["quieter than"],"explanation":"Bir marta comparative yasaladi.","hint":"smaller than / more comfortable than / the best in …","options":["quieter than","more quieter than","quiet than"]},{"id":"en-a2-06-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["My bag is heavier than yours."],"explanation":"Qisqa sifatlarda -er va the -est: small → smaller → the smallest. Happy → happier, big → bigger. Uzunroq sifatlarda more/the most: more comfortable. Good → better → the best, bad → worse → the worst. Ikki narsani than bilan taqqoslaymiz. Guruh ichida the tallest in the class kabi ibora ishlatiladi. More better shakli ikki marta taqqoslashdir.","hint":"smaller than / more comfortable than / the best in …","tokens":["My","bag","is","heavier","than","yours."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-a2-06","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-a2-06","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-a2-06","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-a2-06","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-a2-06","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-a2-06","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-a2-06","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-a2-06","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a2-07','en-a2-07',null,2,7,'published',1,'{"id":"en-a2-07","baseId":"en-a2-07","revision":1,"level":"A2","levelIndex":2,"order":7,"title":"Sifat, ravish va too/enough","objective":"Narsa qanday va ish qanday bajarilishini ajratasiz.","context":"Yo‘l ko‘rsatma va xona qulayligi muhokama qilinadi.","prerequisites":["en-a2-06"],"minutes":40,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Sifat ot yoki to be dan keyin: a careful driver, the room is quiet. Ravish harakatni tasvirlaydi: drives carefully.","Ko‘p ravishlar -ly oladi, ammo good → well, fast → fast istisno. She speaks well — yaxshi gapiradi.","Too + sifat kerakdan ortiqlik; sifat + enough yetarlilik: too small, big enough. Enough + ot: enough space."],"pattern":"a careful driver → drives carefully; too small / big enough","examples":["She speaks slowly.","He is a careful driver.","He drives carefully.","This room is too small.","The bag is light enough.","We have enough space."],"vocabulary":[{"id":"en-a2-07-v0","term":"careful","meaning":"ehtiyotkor","ipa":"/ˈkeəfəl/","collocation":"a careful driver","example":"He is a careful driver."},{"id":"en-a2-07-v1","term":"slowly","meaning":"sekin","ipa":"/ˈsləʊli/","collocation":"speak slowly","example":"She speaks slowly."},{"id":"en-a2-07-v2","term":"space","meaning":"bo‘sh joy","ipa":"/speɪs/","collocation":"enough space","example":"We have enough space."},{"id":"en-a2-07-v3","term":"light","meaning":"yengil","ipa":"/laɪt/","collocation":"a light bag","example":"The bag is light enough."}],"visuals":[{"kind":"compare","title":"Ma’no va tuzilish","items":["a careful driver → drives carefully; too small / big enough","She speaks slowly.","He is a careful driver."]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Yo‘l ko‘rsatma va xona qulayligi muhokama qilinadi.","He drives carefully.","The bag is light enough."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"This room is too small.","audio":"/english-course/v7.23/en-a2-07-dictation.mp3"},"exercises":[{"id":"en-a2-07-choice","type":"choice","skill":"grammar","prompt":"Yetarli kattalikni tanlang.","answers":["big enough"],"explanation":"Enough sifatdan keyin.","hint":"a careful driver → drives carefully; too small / big enough","options":["big enough","enough big","too enough big"]},{"id":"en-a2-07-gap","type":"grammarFill","skill":"grammar","prompt":"He drives ___. (careful)","answers":["carefully"],"explanation":"Sifat ot yoki to be dan keyin: a careful driver, the room is quiet. Ravish harakatni tasvirlaydi: drives carefully. Ko‘p ravishlar -ly oladi, ammo good → well, fast → fast istisno. She speaks well — yaxshi gapiradi. Too + sifat kerakdan ortiqlik; sifat + enough yetarlilik: too small, big enough. Enough + ot: enough space.","hint":"a careful driver → drives carefully; too small / big enough"},{"id":"en-a2-07-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["She speaks slowly."],"explanation":"Sifat ot yoki to be dan keyin: a careful driver, the room is quiet. Ravish harakatni tasvirlaydi: drives carefully. Ko‘p ravishlar -ly oladi, ammo good → well, fast → fast istisno. She speaks well — yaxshi gapiradi. Too + sifat kerakdan ortiqlik; sifat + enough yetarlilik: too small, big enough. Enough + ot: enough space.","hint":"a careful driver → drives carefully; too small / big enough","tokens":["She","speaks","slowly."]},{"id":"en-a2-07-fix","type":"correction","skill":"grammar","prompt":"She speaks good.","answers":["She speaks well."],"explanation":"Sifat ot yoki to be dan keyin: a careful driver, the room is quiet. Ravish harakatni tasvirlaydi: drives carefully. Ko‘p ravishlar -ly oladi, ammo good → well, fast → fast istisno. She speaks well — yaxshi gapiradi. Too + sifat kerakdan ortiqlik; sifat + enough yetarlilik: too small, big enough. Enough + ot: enough space.","hint":"a careful driver → drives carefully; too small / big enough"},{"id":"en-a2-07-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["ehtiyotkor","sekin","bo‘sh joy","yengil"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"a careful driver → drives carefully; too small / big enough","left":["careful","slowly","space","light"],"options":["ehtiyotkor","sekin","bo‘sh joy","yengil"]}],"reading":{"title":"Sifat, ravish va too/enough — vaziyat","text":"Our club wants to show a short film. The first room is too small for twenty people. The second room is big enough, but the sound is too quiet. Ali speaks slowly when he explains the problem. The teacher asks us to check the speakers carefully. After we move them, everyone can hear well. We have enough chairs and enough space. We do not turn the sound up too much because another class is studying next door.","sentences":["Our club wants to show a short film.","The first room is too small for twenty people.","The second room is big enough, but the sound is too quiet.","Ali speaks slowly when he explains the problem.","The teacher asks us to check the speakers carefully.","After we move them, everyone can hear well.","We have enough chairs and enough space.","We do not turn the sound up too much because another class is studying next door."],"questions":[{"id":"en-a2-07-reading0","type":"choice","skill":"reading","prompt":"Birinchi xonaning muammosi nima?","answers":["too small"],"explanation":"Too small for twenty people.","hint":"a careful driver → drives carefully; too small / big enough","options":["too small","too bright","too quiet"]},{"id":"en-a2-07-reading1","type":"choice","skill":"reading","prompt":"Spikerlar ko‘chirilgach nima o‘zgardi?","answers":["everyone can hear well"],"explanation":"Hear well — natija.","hint":"a careful driver → drives carefully; too small / big enough","options":["everyone can hear well","the film got shorter","chairs disappeared"]},{"id":"en-a2-07-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"a careful driver → drives carefully; too small / big enough","options":["Our club wants to show a short film.","The first room is too small for twenty people.","The second room is big enough, but the sound is too quiet.","Ali speaks slowly when he explains the problem.","The teacher asks us to check the speakers carefully.","After we move them, everyone can hear well.","We have enough chairs and enough space.","We do not turn the sound up too much because another class is studying next door."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"The first room is too small. The second is big enough. Please speak slowly and check the speakers carefully. Now everyone can hear well. We have enough chairs.","audio":"/english-course/v7.23/en-a2-07.mp3","synthetic":true,"questions":[{"id":"en-a2-07-listening0","type":"choice","skill":"listening","prompt":"Qaysi xona yetarlicha katta?","answers":["the second"],"explanation":"The second is big enough.","hint":"a careful driver → drives carefully; too small / big enough","options":["the second","the first","neither"]},{"id":"en-a2-07-listening1","type":"choice","skill":"listening","prompt":"Qanday gapirish so‘raladi?","answers":["slowly"],"explanation":"Please speak slowly.","hint":"a careful driver → drives carefully; too small / big enough","options":["slowly","loudly","angrily"]},{"id":"en-a2-07-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["second","slowly"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"a careful driver → drives carefully; too small / big enough","rows":["Yetarli katta xona","Gapirish usuli"]},{"id":"en-a2-07-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["This room is too small."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"a careful driver → drives carefully; too small / big enough","audio":"/english-course/v7.23/en-a2-07-dictation.mp3","transcript":"This room is too small."}]},"writing":{"task":"Bir xonaning muammolari va yechimini too/enough hamda ikki ravish bilan yozing.","audience":"Sinfdagi sherigingiz","minWords":52,"maxWords":140,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"Our first room was too small for the group. We moved to a bigger room with enough chairs. The teacher spoke slowly and explained the task clearly. The room was quiet enough for listening. We checked the audio carefully and did not play it too loudly because students were working next door.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["She speaks slowly.","He is a careful driver.","He drives carefully."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Bir vazifa uchun joy qulayligini baholang va qanday ishlash kerakligini ayting.","seconds":50,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot"