insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a2-08','en-a2-08',null,2,8,'published',1,'{"id":"en-a2-08","baseId":"en-a2-08","revision":1,"level":"A2","levelIndex":2,"order":8,"title":"A few, few, a little va little","objective":"Miqdor kamligi va yetarliligini ma’noga qarab ifodalaysiz.","context":"Sayrga qolgan vaqt va oziq-ovqat baholanadi.","prerequisites":["en-a2-07"],"minutes":40,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["A few ko‘plik sanaladigan ot bilan oz bo‘lsa ham bor degani. Few juda kam, ko‘pincha yetarli emas ma’nosini beradi.","A little sanalmaydigan ot bilan ozgina bor; little juda kamligini ko‘rsatadi. A little water va little water bir xil ohang emas.","Miqdor aniq raqam bo‘lmasligi mumkin. Matndagi vazifa va so‘zlovchining bahosiga qarab yetarlilikni tushuning."],"pattern":"a few apples / few apples; a little time / little time","examples":["We have a few apples.","There are few buses today.","I have a little time.","We have little water left.","There are a few seats available.","She adds a little milk."],"vocabulary":[{"id":"en-a2-08-v0","term":"left","meaning":"qolgan","ipa":"/left/","collocation":"water left","example":"We have little water left."},{"id":"en-a2-08-v1","term":"available","meaning":"mavjud, bo‘sh","ipa":"/əˈveɪləbəl/","collocation":"seats available","example":"There are a few seats available."},{"id":"en-a2-08-v2","term":"seat","meaning":"o‘rindiq","ipa":"/siːt/","collocation":"a few seats","example":"There are a few seats available."},{"id":"en-a2-08-v3","term":"add","meaning":"qo‘shmoq","ipa":"/æd/","collocation":"add a little milk","example":"She adds a little milk."}],"visuals":[{"kind":"menu","title":"Ma’no va tuzilish","items":["a few apples / few apples; a little time / little time","We have a few apples.","There are few buses today."]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Sayrga qolgan vaqt va oziq-ovqat baholanadi.","I have a little time.","There are a few seats available."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"We have little water left.","audio":"/english-course/v7.23/en-a2-08-dictation.mp3"},"exercises":[{"id":"en-a2-08-choice","type":"choice","skill":"grammar","prompt":"Water bilan qaysi miqdor mos?","answers":["a little"],"explanation":"Water sanalmaydigan ot.","hint":"a few apples / few apples; a little time / little time","options":["a little","a few","many"]},{"id":"en-a2-08-gap","type":"grammarFill","skill":"grammar","prompt":"We have a ___ apples.","answers":["few"],"explanation":"A few ko‘plik sanaladigan ot bilan oz bo‘lsa ham bor degani. Few juda kam, ko‘pincha yetarli emas ma’nosini beradi. A little sanalmaydigan ot bilan ozgina bor; little juda kamligini ko‘rsatadi. A little water va little water bir xil ohang emas. Miqdor aniq raqam bo‘lmasligi mumkin. Matndagi vazifa va so‘zlovchining bahosiga qarab yetarlilikni tushuning.","hint":"a few apples / few apples; a little time / little time"},{"id":"en-a2-08-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["We have a few apples."],"explanation":"A few ko‘plik sanaladigan ot bilan oz bo‘lsa ham bor degani. Few juda kam, ko‘pincha yetarli emas ma’nosini beradi. A little sanalmaydigan ot bilan ozgina bor; little juda kamligini ko‘rsatadi. A little water va little water bir xil ohang emas. Miqdor aniq raqam bo‘lmasligi mumkin. Matndagi vazifa va so‘zlovchining bahosiga qarab yetarlilikni tushuning.","hint":"a few apples / few apples; a little time / little time","tokens":["We","have","a","few","apples."]},{"id":"en-a2-08-fix","type":"correction","skill":"grammar","prompt":"I have a few water.","answers":["I have a little water."],"explanation":"A few ko‘plik sanaladigan ot bilan oz bo‘lsa ham bor degani. Few juda kam, ko‘pincha yetarli emas ma’nosini beradi. A little sanalmaydigan ot bilan ozgina bor; little juda kamligini ko‘rsatadi. A little water va little water bir xil ohang emas. Miqdor aniq raqam bo‘lmasligi mumkin. Matndagi vazifa va so‘zlovchining bahosiga qarab yetarlilikni tushuning.","hint":"a few apples / few apples; a little time / little time"},{"id":"en-a2-08-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["qolgan","mavjud, bo‘sh","o‘rindiq","qo‘shmoq"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"a few apples / few apples; a little time / little time","left":["left","available","seat","add"],"options":["qolgan","mavjud, bo‘sh","o‘rindiq","qo‘shmoq"]},{"id":"en-a2-08-dialogue","type":"dialogue","skill":"grammar","prompt":"Sherik: “Can you give one example?” Siz: darsdagi birinchi namunani qayta tuzing.","answers":["We have a few apples."],"tokens":["We","have","a","few","apples."],"hint":"a few apples / few apples; a little time / little time","explanation":"A few ko‘plik sanaladigan ot bilan oz bo‘lsa ham bor degani. Few juda kam, ko‘pincha yetarli emas ma’nosini beradi."},{"id":"en-a2-08-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Kelajak: will va going to: Ko‘rinib turgan dalil bilan taxminni tanlang.","answers":["Look at the clouds. It’s going to rain."],"explanation":"Dark clouds hozirgi dalil.","hint":"We are going to … / I will … / We are meeting on Saturday.","options":["Look at the clouds. It’s going to rain.","It raining yesterday.","We rain clouds."],"recap":true,"sourceLesson":"Kelajak: will va going to"},{"id":"en-a2-08-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Taqqoslash va eng yuqori daraja: Good ning eng yuqori shakli?","answers":["the best"],"explanation":"Good → better → the best.","hint":"smaller than / more comfortable than / the best in …","options":["the best","the goodest","the most good"],"recap":true,"sourceLesson":"Taqqoslash va eng yuqori daraja"},{"id":"en-a2-08-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Sifat, ravish va too/enough: Yetarli kattalikni tanlang.","answers":["big enough"],"explanation":"Enough sifatdan keyin.","hint":"a careful driver → drives carefully; too small / big enough","options":["big enough","enough big","too enough big"],"recap":true,"sourceLesson":"Sifat, ravish va too/enough"}],"reading":{"title":"A few, few, a little va little — vaziyat","text":"Our picnic starts in half an hour. We have a few apples, so each small group can share one. There is a little water in the first bottle, but it is not enough for everyone. Ali buys two more bottles. There are few buses on Sunday, so we decide to walk to the nearby park. We still have a little time to check our bags. After the trip, very little rubbish is left because everyone uses reusable cups.","sentences":["Our picnic starts in half an hour.","We have a few apples, so each small group can share one.","There is a little water in the first bottle, but it is not enough for everyone.","Ali buys two more bottles.","There are few buses on Sunday, so we decide to walk to the nearby park.","We still have a little time to check our bags.","After the trip, very little rubbish is left because everyone uses reusable cups."],"questions":[{"id":"en-a2-08-reading0","type":"choice","skill":"reading","prompt":"Nega piyoda borishadi?","answers":["there are few buses"],"explanation":"Few buses — avtobuslar kam.","hint":"a few apples / few apples; a little time / little time","options":["there are few buses","they have many bags","the park is closed"]},{"id":"en-a2-08-reading1","type":"choice","skill":"reading","prompt":"Nega yana suv olinadi?","answers":["the first bottle is not enough"],"explanation":"Not enough for everyone — maqsad.","hint":"a few apples / few apples; a little time / little time","options":["the first bottle is not enough","everyone dislikes apples","there is too much water"]},{"id":"en-a2-08-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"a few apples / few apples; a little time / little time","options":["Our picnic starts in half an hour.","We have a few apples, so each small group can share one.","There is a little water in the first bottle, but it is not enough for everyone.","Ali buys two more bottles.","There are few buses on Sunday, so we decide to walk to the nearby park.","We still have a little time to check our bags.","After the trip, very little rubbish is left because everyone uses reusable cups."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"We have a few apples and a little water. There are few buses today. Ali will buy two more bottles, and then we can walk to the park. We still have a little time.","audio":"/english-course/v7.23/en-a2-08.mp3","synthetic":true,"questions":[{"id":"en-a2-08-listening0","type":"choice","skill":"listening","prompt":"Ali nechta idish oladi?","answers":["two"],"explanation":"Two more bottles.","hint":"a few apples / few apples; a little time / little time","options":["two","three","one"]},{"id":"en-a2-08-listening1","type":"choice","skill":"listening","prompt":"Yo‘l qanday bo‘ladi?","answers":["walking"],"explanation":"Walk to the park.","hint":"a few apples / few apples; a little time / little time","options":["walking","by train","by taxi"]},{"id":"en-a2-08-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["two","walking"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"a few apples / few apples; a little time / little time","rows":["Yangi idishlar","Yo‘l usuli"]},{"id":"en-a2-08-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["We have little water left."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"a few apples / few apples; a little time / little time","audio":"/english-course/v7.23/en-a2-08-dictation.mp3","transcript":"We have little water left."}]},"writing":{"task":"Sayrga tayyorgarlik haqida kam, yetarli va yetmaydigan miqdorlarni yozing.","audience":"Sinfdagi sherigingiz","minWords":50,"maxWords":140,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"We have a few sandwiches for the group and a little fruit. There is little water left, so we need more bottles. Few shops are open on Sunday. We still have a little time before the trip. I will check the nearest shop while my friend prepares the reusable cups.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["We have a few apples.","There are few buses today.","I have a little time."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Miqdorni shunchaki sanamang; bor narsa yetarlimi, shuni ham ayting.","seconds":50,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Sayrga tayyorgarlik haqida kam, yetarli va yetmaydigan miqdorlarni yozing.","exit":[[{"id":"en-a2-08-exit0","type":"grammarFill","skill":"grammar","prompt":"a ___ seats","a