d":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied.","recapQuestions":[{"id":"en-a2-08-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Kelajak: will va going to: Ko‘rinib turgan dalil bilan taxminni tanlang.","answers":["Look at the clouds. It’s going to rain."],"explanation":"Dark clouds hozirgi dalil.","hint":"We are going to … / I will … / We are meeting on Saturday.","options":["Look at the clouds. It’s going to rain.","It raining yesterday.","We rain clouds."],"recap":true,"sourceLesson":"Kelajak: will va going to"},{"id":"en-a2-08-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Taqqoslash va eng yuqori daraja: Good ning eng yuqori shakli?","answers":["the best"],"explanation":"Good → better → the best.","hint":"smaller than / more comfortable than / the best in …","options":["the best","the goodest","the most good"],"recap":true,"sourceLesson":"Taqqoslash va eng yuqori daraja"},{"id":"en-a2-08-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Sifat, ravish va too/enough: Yetarli kattalikni tanlang.","answers":["big enough"],"explanation":"Enough sifatdan keyin.","hint":"a careful driver → drives carefully; too small / big enough","options":["big enough","enough big","too enough big"],"recap":true,"sourceLesson":"Sifat, ravish va too/enough"}]}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a2-09','en-a2-09',null,2,9,'published',1,'{"id":"en-a2-09","baseId":"en-a2-09","revision":1,"level":"A2","levelIndex":2,"order":9,"title":"Majburiyat, taqiq va erkin tanlov","objective":"Mustn’t va don’t have to farqini vaziyat orqali tushuntirasiz.","context":"Maktab ustaxonasining qoidalari o‘qiladi.","prerequisites":["en-a2-08"],"minutes":40,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Have to tashqi qoida yoki vaziyat sabab zarur ishni bildiradi. Must gapiruvchining kuchli talabi bo‘lishi mumkin.","Mustn’t — taqiq; don’t have to — shart emas, ammo mumkin. Ularni bir ma’noda ishlatmang.","Savolda do/does + have to; o‘tgan majburiyatda had to. Mustdan keyin fe’lning asosiy shakli keladi."],"pattern":"have to wear / mustn’t touch / don’t have to bring","examples":["We have to wear safety glasses.","You must not touch the hot tool.","You do not have to bring paper.","Does she have to arrive early?","Yesterday we had to clean the tables.","You can bring your own notebook."],"vocabulary":[{"id":"en-a2-09-v0","term":"rule","meaning":"qoida","ipa":"/ruːl/","collocation":"follow a rule","example":"Our school workshop has clear rules."},{"id":"en-a2-09-v1","term":"tool","meaning":"asbob","ipa":"/tuːl/","collocation":"a hot tool","example":"You must not touch the hot tool."},{"id":"en-a2-09-v2","term":"required","meaning":"talab etilgan","ipa":"/rɪˈkwaɪəd/","collocation":"required equipment","example":"required equipment"},{"id":"en-a2-09-v3","term":"optional","meaning":"ixtiyoriy","ipa":"/ˈɒpʃənəl/","collocation":"an optional notebook","example":"A notebook is optional, but it is useful for planning."}],"visuals":[{"kind":"sentence","title":"Ma’no va tuzilish","items":["have to wear / mustn’t touch / don’t have to bring","We have to wear safety glasses.","You must not touch the hot tool."]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Maktab ustaxonasining qoidalari o‘qiladi.","You do not have to bring paper.","Yesterday we had to clean the tables."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"Does she have to arrive early?","audio":"/english-course/v7.23/en-a2-09-dictation.mp3"},"exercises":[{"id":"en-a2-09-choice","type":"choice","skill":"grammar","prompt":"Shart emas, lekin mumkin degan gap?","answers":["You do not have to bring a notebook."],"explanation":"Don’t have to erkin tanlov.","hint":"have to wear / mustn’t touch / don’t have to bring","options":["You do not have to bring a notebook.","You must not bring a notebook.","You cannot bring a notebook."]},{"id":"en-a2-09-gap","type":"grammarFill","skill":"grammar","prompt":"Yesterday we ___ to clean the tables.","answers":["had"],"explanation":"Have to tashqi qoida yoki vaziyat sabab zarur ishni bildiradi. Must gapiruvchining kuchli talabi bo‘lishi mumkin. Mustn’t — taqiq; don’t have to — shart emas, ammo mumkin. Ularni bir ma’noda ishlatmang. Savolda do/does + have to; o‘tgan majburiyatda had to. Mustdan keyin fe’lning asosiy shakli keladi.","hint":"have to wear / mustn’t touch / don’t have to bring"},{"id":"en-a2-09-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["We have to wear safety glasses."],"explanation":"Have to tashqi qoida yoki vaziyat sabab zarur ishni bildiradi. Must gapiruvchining kuchli talabi bo‘lishi mumkin. Mustn’t — taqiq; don’t have to — shart emas, ammo mumkin. Ularni bir ma’noda ishlatmang. Savolda do/does + have to; o‘tgan majburiyatda had to. Mustdan keyin fe’lning asosiy shakli keladi.","hint":"have to wear / mustn’t touch / don’t have to bring","tokens":["We","have","to","wear","safety","glasses."]},{"id":"en-a2-09-fix","type":"correction","skill":"grammar","prompt":"She have to arrive early.","answers":["She has to arrive early."],"explanation":"Have to tashqi qoida yoki vaziyat sabab zarur ishni bildiradi. Must gapiruvchining kuchli talabi bo‘lishi mumkin. Mustn’t — taqiq; don’t have to — shart emas, ammo mumkin. Ularni bir ma’noda ishlatmang. Savolda do/does + have to; o‘tgan majburiyatda had to. Mustdan keyin fe’lning asosiy shakli keladi.","hint":"have to wear / mustn’t touch / don’t have to bring"},{"id":"en-a2-09-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["qoida","asbob","talab etilgan","ixtiyoriy"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"have to wear / mustn’t touch / don’t have to bring","left":["rule","tool","required","optional"],"options":["qoida","asbob","talab etilgan","ixtiyoriy"]},{"id":"en-a2-09-collocations","type":"collocation","skill":"vocabulary","prompt":"So‘zlarni darsdagi birikmasi bilan moslang.","left":["rule","tool","required","optional"],"options":["follow a rule","a hot tool","required equipment","an optional notebook"],"answers":["follow a rule","a hot tool","required equipment","an optional notebook"],"hint":"So‘z qaysi birikmada ishlatilishini eslang.","explanation":"Birikmani yozgan gapingizda ham ishlating."}],"reading":{"title":"Majburiyat, taqiq va erkin tanlov — vaziyat","text":"Our school workshop has clear rules. Everyone has to wear safety glasses near the tools. Students must not touch a hot tool, even when the teacher is close. We do not have to bring paper because the school provides it. A notebook is optional, but it is useful for planning. Yesterday we had to clean the tables before the next group arrived. A new student thought that “do not have to bring a notebook” meant notebooks were forbidden. The teacher explained that it was a choice, not a ban. We read the rules again and separated necessary actions from choices. Clear language helps us work together without confusion.","sentences":["Our school workshop has clear rules.","Everyone has to wear safety glasses near the tools.","Students must not touch a hot tool, even when the teacher is close.","We do not have to bring paper because the school provides it.","A notebook is optional, but it is useful for planning.","Yesterday we had to clean the tables before the next group arrived.","A new student thought that “do not have to bring a notebook” meant notebooks were forbidden.","The teacher explained that it was a choice, not a ban.","We read the rules again and separated necessary actions from choices.","Clear language helps us work together without confusion."],"questions":[{"id":"en-a2-09-reading0","type":"choice","skill":"reading","prompt":"Daftar olib kelish mumkinmi?","answers":["Yes, it is optional"],"explanation":"Shart emas degani taqiq emas.","hint":"have to wear / mustn’t touch / don’t have to bring","options":["Yes, it is optional","No, it is forbidden","Only yesterday"]},{"id":"en-a2-09-reading1","type":"choice","skill":"reading","prompt":"Nima taqiqlangan?","answers":["touching a hot tool"],"explanation":"Must not touch taqiq.","hint":"have to wear / mustn’t touch / don’t have to bring","options":["touching a hot tool","wearing glasses","bringing a notebook"]},{"id":"en-a2-09-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"have to wear / mustn’t touch / don’t have to bring","options":["Our school workshop has clear rules.","Everyone has to wear safety glasses near the tools.","Students must not touch a hot tool, even when the teacher is close.","We do not have to bring paper because the school provides it.","A notebook is optional, but it is useful for planning.","Yesterday we had to clean the tables before the next group arrived.","A new student thought that “do not have to bring a notebook” meant notebooks were forbidden.","The teacher explained that it was a choice, not a ban.","We read the rules again and separated necessary actions from choices.","Clear language helps us work together without confusion."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"Welcome to the workshop. You have to wear safety glasses. You must not touch a hot tool. You do not have to bring paper. The school provides it. You can bring a notebook if you want.","audio":"/english-course/v7.23/en-a2-09.mp3","synthetic":true,"questions":[{"id":"en-a2-09-listening0","type":"choice","skill":"listening","prompt":"Qog‘ozni kim beradi?","answers":["the school"],"explanation":"School provides it.","hint":"have to wear / mustn’t touch / don’t have to bring","options":["the school","the student only","nobody"]},{"id":"en-a2-09-listening1","type":"choice","skill":"listening","prompt":"Ko‘zoynak zarurmi?","answers":["Yes"],"explanation":"Have to wear.","hint":"have to wear / mustn’t touch / don’t have to bring","options":["Yes","No","Only at home"]},{"id":"en-a2-09-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["safety glasses","paper"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"have to wear / mustn’t touch / don’t have to bring","rows":["Zarur jihoz","Maktab beradigan narsa"]},{"id":"en-a2-09-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["Does she have to arrive early?"],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"have to wear / mustn’t touch / don’t have to bring","audio":"/english-course/v7.23/en-a2-09-dictation.mp3","transcript":"Does she have to arrive early?"}]},"writing":{"task":"Kutubxona yoki ustaxona uchun zarur ish, taqiq va ixtiyoriy ishni ajratib qoida yozing.","audience":"Sinfdagi sherigingiz","minWords":55,"maxWords":140,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"In our workshop, we have to wear safety glasses near the tools. We must not touch a hot tool or leave a bag in the walking area. We do not have to bring paper because the school provides it. A notebook is optional. Yesterday we had to clean the tables before leaving. Please read the rules and ask the teacher if a choice is unclear.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["We have to wear safety glasses.","You must not touch the hot tool.","You do not have to bring paper."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Yangi o‘quvchiga bir majburiyat, bir taqiq va bir ixtiyoriy tanlovni tushuntiring.","seconds":50,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Kutubxona yoki ustaxona uchun zarur ish, taqiq va ixtiyoriy ishni ajratib qoida yozing.","exit":[[{"id":"en-a2-09-exit0","type":"grammarFill","skill":"grammar","prompt":"She ___ to wear glasses.","answers":["has"],"explanation":"Have to tashqi qoida yoki vaziyat sabab zarur ishni bildiradi. Must gapiruvchining kuchli talabi bo‘lishi mumkin. Mustn’t — taqiq; don’t have to — shart emas, ammo mumkin. Ularni bir ma’noda ishlatmang. Savolda do/does + have to; o‘tgan majburiyatda had to. Mustdan keyin fe’lning asosiy shakli keladi.","hint":"have to wear / mustn’t touch / don’t have to bring"},{"id":"en-a2-09-exit1","type":"grammarFill","skill":"grammar","prompt":"We ___ not touch a hot tool.","answers":["must"],"explanation":"Have to tashqi qoida yoki vaziyat sabab zarur ishni bildiradi. Must gapiruvchining kuchli talabi bo‘lishi mumkin. Mustn’t — taqiq; don’t have to — shart emas, ammo mumkin. Ularni bir ma’noda ishlatmang. Savolda do/does + have to; o‘tgan majburiyatda had to. Mustdan keyin fe’lning asosiy shakli keladi.","hint":"have to wear / mustn’t touch / don’t have to bring"},{"id":"en-a2-09-exit2","type":"grammarFill","skill":"grammar","prompt":"___ he have to arrive early?","answers":["Does"],"explanation":"Have to tashqi qoida yoki vaziyat sabab zarur ishni bildiradi. Must gapiruvchining kuchli talabi bo‘lishi mumkin. Mustn’t — taqiq; don’t have to — shart emas, ammo mumkin. Ularni bir ma’noda ishlatmang. Savolda do/does + have to; o‘tgan majburiyatda had to. Mustdan keyin fe’lning asosiy shakli keladi.","hint":"have to wear / mustn’t touch / don’t have to bring"},{"id":"en-a2-09-exit3","type":"choice","skill":"grammar","prompt":"Taqiq qaysi?","answers":["must not"],"explanation":"Must not taqiq.","hint":"have to wear / mustn’t touch / don’t have to bring","options":["must not","do not have to","may"]},{"id":"en-a2-09-exit4","type":"grammarFill","skill":"grammar","prompt":"Yesterday we ___ to clean.","answers":["had"],"explanation":"Have to tashqi qoida yoki vaziyat sabab zarur ishni bildiradi. Must gapiruvchining kuchli talabi bo‘lishi mumkin. Mustn’t — taqiq; don’t have to — shart emas, ammo mumkin. Ularni bir ma’noda ishlatmang. Savolda do/does + have to; o‘tgan majburiyatda had to. Mustdan keyin fe’lning asosiy shakli keladi.","hint":"have to wear / mustn’t touch / don’t have to bring"}],[{"id":"en-a2-09-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["You must not touch the hot tool."],"explanation":"Have to tashqi qoida yoki vaziyat sabab zarur ishni bildiradi. Must gapiruvchining kuchli talabi bo‘lishi mumkin. Mustn’t — taqiq; don’t have to — shart emas, ammo mumkin. Ularni bir ma’noda ishlatmang. Savolda do/does + have to; o‘tgan majburiyatda had to. Mustdan keyin fe’lning asosiy shakli keladi.","hint":"have to wear / mustn’t touch / don’t have to bring","tokens":["You","must","not","touch","the","hot","tool."]},{"id":"en-a2-09-exit-b1","type":"grammarFill","skill":"grammar","prompt":"We ___ not touch a hot tool.","answers":["must"],"explanation":"Have to tashqi qoida yoki vaziyat sabab zarur ishni bildiradi. Must gapiruvchining kuchli talabi bo‘lishi mumkin. Mustn’t — taqiq; don’t have to — shart emas, ammo mumkin. Ularni bir ma’noda ishlatmang. Savolda do/does + have to; o‘tgan majburiyatda had to. Mustdan keyin fe’lning asosiy shakli keladi.","hint":"have to wear / mustn’t touch / don’t have to bring"},{"id":"en-a2-09-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Does she have to arrive early?"],"explanation":"Have to tashqi qoida yoki vaziyat sabab zarur ishni bildiradi. Must gapiruvchining kuchli talabi bo‘lishi mumkin. Mustn’t — taqiq; don’t have to — shart emas, ammo mumkin. Ularni bir ma’noda ishlatmang. Savolda do/does + have to; o‘tgan majburiyatda had to. Mustdan keyin fe’lning asosiy shakli keladi.","hint":"have to wear / mustn’t touch / don’t have to bring","tokens":["Does","she","have","to","arrive","early?"]},{"id":"en-a2-09-exit-b3","type":"choice","skill":"grammar","prompt":"Taqiq qaysi?","answers":["must not"],"explanation":"Must not taqiq.","hint":"have to wear / mustn’t touch / don’t have to bring","options":["must not","do not have to","may"]},{"id":"en-a2-09-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["You can bring your own notebook."],"explanation":"Have to tashqi qoida yoki vaziyat sabab zarur ishni bildiradi. Must gapiruvchining kuchli talabi bo‘lishi mumkin. Mustn’t — taqiq; don’t have to — shart emas, ammo mumkin. Ularni bir ma’noda ishlatmang. Savolda do/does + have to; o‘tgan majburiyatda had to. Mustdan keyin fe’lning asosiy shakli keladi.","hint":"have to wear / mustn’t touch / don’t have to bring","tokens":["You","can","bring","your","own","notebook."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-a2-09","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-a2-09","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-a2-09","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-a2-09","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-a2-09","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-a2-09","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-a2-09","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-a2-09","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a2-10','en-a2-10',null,2,10,'published',1,'{"id":"en-a2-10","baseId":"en-a2-10","revision":1,"level":"A2","levelIndex":2,"order":10,"title":"Should va odobli so‘rovlar","objective":"Maslahat berasiz va yordamni muloyim so‘raysiz.","context":"Do‘stingiz imtihon oldidan rejasi bo‘yicha yordam so‘raydi.","prerequisites":["en-a2-09"],"minutes":40,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Should + asosiy fe’l maslahat: You should rest. Shouldn’t qilmaslik tavsiyasi. Bu har doim majburiy qoida emas.","Could you …? va Would you …? kundalik odobli so‘rov. Could bu yerda o‘tgan zamon haqida emas.","Can I …? ruxsat, Could you …? suhbatdoshning yordam amali. Please odobni kuchaytiradi, lekin ohang ham muhim."],"pattern":"You should … / Could you …, please? / Would you mind + -ing?","examples":["You should take a short break.","You shouldn’t study all night.","Could you explain this word, please?","Can I borrow your dictionary?","Would you help me with the plan?","You should drink some water."],"vocabulary":[{"id":"en-a2-10-v0","term":"break","meaning":"tanaffus","ipa":"/breɪk/","collocation":"take a break","example":"You should take a short break."},{"id":"en-a2-10-v1","term":"explain","meaning":"tushuntirmoq","ipa":"/ɪkˈspleɪn/","collocation":"explain a word","example":"Could you explain this word, please?"},{"id":"en-a2-10-v2","term":"borrow","meaning":"vaqtincha olmoq","ipa":"/ˈbɒrəʊ/","collocation":"borrow a dictionary","example":"Can I borrow your dictionary?"},{"id":"en-a2-10-v3","term":"rest","meaning":"dam olmoq","ipa":"/rest/","collocation":"get some rest","example":"He wants to study all night, but Lola says he should make a short plan and get some rest."}],"visuals":[{"kind":"dialogue","title":"Ma’no va tuzilish","items":["You should … / Could you …, please? / Would you mind + -ing?","You should take a short break.","You shouldn’t study all night."]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Do‘stingiz imtihon oldidan rejasi bo‘yicha yordam so‘raydi.","Could you explain this word, please?","Would you help me with the plan?"]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"Can I borrow your dictionary?","audio":"/english-course/v7.23/en-a2-10-dictation.mp3"},"exercises":[{"id":"en-a2-10-choice","type":"choice","skill":"grammar","prompt":"Odobli so‘rovni tanlang.","answers":["Could you explain this, please?"],"explanation":"Could you … please? so‘rov.","hint":"You should … / Could you …, please? / Would you mind + -ing?","options":["Could you explain this, please?","You must explain now!","Explain me you?"]},{"id":"en-a2-10-gap","type":"grammarFill","skill":"grammar","prompt":"You should ___ a break. (take)","answers":["take"],"explanation":"Should + asosiy fe’l maslahat: You should rest. Shouldn’t qilmaslik tavsiyasi. Bu har doim majburiy qoida emas. Could you …? va Would you …? kundalik odobli so‘rov. Could bu yerda o‘tgan zamon haqida emas. Can I …? ruxsat, Could you …? suhbatdoshning yordam amali. Please odobni kuchaytiradi, lekin ohang ham muhim.","hint":"You should … / Could you …, please? / Would you mind + -ing?"},{"id":"en-a2-10-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["You should take a short break."],"explanation":"Should + asosiy fe’l maslahat: You should rest. Shouldn’t qilmaslik tavsiyasi. Bu har doim majburiy qoida emas. Could you …? va Would you …? kundalik odobli so‘rov. Could bu yerda o‘tgan zamon haqida emas. Can I …? ruxsat, Could you …? suhbatdoshning yordam amali. Please odobni kuchaytiradi, lekin ohang ham muhim.","hint":"You should … / Could you …, please? / Would you mind + -ing?","tokens":["You","should","take","a","short","break."]},{"id":"en-a2-10-fix","type":"correction","skill":"grammar","prompt":"Could you to help me?","answers":["Could you help me?"],"explanation":"Should + asosiy fe’l maslahat: You should rest. Shouldn’t qilmaslik tavsiyasi. Bu har doim majburiy qoida emas. Could you …? va Would you …? kundalik odobli so‘rov. Could bu yerda o‘tgan zamon haqida emas. Can I …? ruxsat, Could you …? suhbatdoshning yordam amali. Please odobni kuchaytiradi, lekin ohang ham muhim.","hint":"You should … / Could you …, please? / Would you mind + -ing?"},{"id":"en-a2-10-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["tanaffus","tushuntirmoq","vaqtincha olmoq","dam olmoq"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"You should … / Could you …, please? / Would you mind + -ing?","left":["break","explain","borrow","rest"],"options":["tanaffus","tushuntirmoq","vaqtincha olmoq","dam olmoq"]}],"reading":{"title":"Should va odobli so‘rovlar — vaziyat","text":"Ali has an English test tomorrow. He wants to study all night, but Lola says he should make a short plan and get some rest. Ali asks, “Could you explain this exercise, please?” Lola shows him one example, then asks him to try the next question himself. He borrows her dictionary and checks two words. They take a short break after twenty minutes. Ali feels more confident because he understands the task instead of simply copying the answers.","sentences":["Ali has an English test tomorrow.","He wants to study all night, but Lola says he should make a short plan and get some rest.","Ali asks, “Could you explain this exercise, please?","” Lola shows him one example, then asks him to try the next question himself.","He borrows her dictionary and checks two words.","They take a short break after twenty minutes.","Ali feels more confident because he understands the task instead of simply copying the answers."],"questions":[{"id":"en-a2-10-reading0","type":"choice","skill":"reading","prompt":"Lola nimani tavsiya qiladi?","answers":["a short plan and rest"],"explanation":"Should make a short plan and get rest.","hint":"You should … / Could you …, please? / Would you mind + -ing?","options":["a short plan and rest","studying all night","copying every answer"]},{"id":"en-a2-10-reading1","type":"choice","skill":"reading","prompt":"Ali nega ishonchliroq bo‘ldi?","answers":["he understood the task"],"explanation":"Understands the task instead of copying.","hint":"You should … / Could you …, please? / Would you mind + -ing?","options":["he understood the task","he saw tomorrow’s test","he finished school"]},{"id":"en-a2-10-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"You should … / Could you …, please? / Would you mind + -ing?","options":["Ali has an English test tomorrow.","He wants to study all night, but Lola says he should make a short plan and get some rest.","Ali asks, “Could you explain this exercise, please?","” Lola shows him one example, then asks him to try the next question himself.","He borrows her dictionary and checks two words.","They take a short break after twenty minutes.","Ali feels more confident because he understands the task instead of simply copying the answers."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"You should take a short break, Ali. You shouldn’t study all night. Could you show me the exercise? We can do one example together, then you should try the next question yourself.","audio":"/english-course/v7.23/en-a2-10.mp3","synthetic":true,"questions":[{"id":"en-a2-10-listening0","type":"choice","skill":"listening","prompt":"Nima tavsiya qilinmaydi?","answers":["studying all night"],"explanation":"Shouldn’t study all night.","hint":"You should … / Could you …, please? / Would you mind + -ing?","options":["studying all night","taking a break","trying a question"]},{"id":"en-a2-10-listening1","type":"choice","skill":"listening","prompt":"Keyingi savolni kim bajaradi?","answers":["Ali himself"],"explanation":"Try the next question yourself.","hint":"You should … / Could you …, please? / Would you mind + -ing?","options":["Ali himself","Lola alone","the teacher"]},{"id":"en-a2-10-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["break","try the next question"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"You should … / Could you …, please? / Would you mind + -ing?","rows":["Tavsiya","Keyingi ish"]},{"id":"en-a2-10-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["Can I borrow your dictionary?"],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"You should … / Could you …, please? / Would you mind + -ing?","audio":"/english-course/v7.23/en-a2-10-dictation.mp3","transcript":"Can I borrow your dictionary?"}]},"writing":{"task":"Testga tayyorlanayotgan do‘stingizga uch tavsiya va bitta odobli so‘rov yozing.","audience":"Sinfdagi sherigingiz","minWords":55,"maxWords":140,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"Hi Ali, you should make a short plan for your test. You shouldn’t study all night because you need rest. Try one exercise, check the explanation, and take a break. Could you send me the question you find difficult, please? I can explain an example, but you should write your own answer so that you really learn.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["You should take a short break.","You shouldn’t study all night.","Could you explain this word, please?"],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Maslahat so‘rang, ikkita tavsiya bering va bir odobli so‘rovga javob bering.","seconds":50,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Testga tayyorlanayotgan do‘stingizga uch tavsiya va bitta odobli so‘rov yozing.","exit":[[{"id":"en-a2-10-exit0","type":"grammarFill","skill":"grammar","prompt":"You ___ rest. (maslahat)","answers":["should"],"explanation":"Should + asosiy fe’l maslahat: You should rest. Shouldn’t qilmaslik tavsiyasi. Bu har doim majburiy qoida emas. Could you …? va Would you …? kundalik odobli so‘rov. Could bu yerda o‘tgan zamon haqida emas. Can I …? ruxsat, Could you …? suhbatdoshning yordam amali. Please odobni kuchaytiradi, lekin ohang ham muhim.","hint":"You should … / Could you …, please? / Would you mind + -ing?"},{"id":"en-a2-10-exit1","type":"grammarFill","skill":"grammar","prompt":"Could you ___ me?","answers":["help"],"explanation":"Should + asosiy fe’l maslahat: You should rest. Shouldn’t qilmaslik tavsiyasi. Bu har doim majburiy qoida emas. Could you …? va Would you …? kundalik odobli so‘rov. Could bu yerda o‘tgan zamon haqida emas. Can I …? ruxsat, Could you …? suhbatdoshning yordam amali. Please odobni kuchaytiradi, lekin ohang ham muhim.","hint":"You should … / Could you …, please? / Would you mind + -ing?"},{"id":"en-a2-10-exit2","type":"grammarFill","skill":"grammar","prompt":"You shouldn’t ___ all night.","answers":["study"],"explanation":"Should + asosiy fe’l maslahat: You should rest. Shouldn’t qilmaslik tavsiyasi. Bu har doim majburiy qoida emas. Could you …? va Would you …? kundalik odobli so‘rov. Could bu yerda o‘tgan zamon haqida emas. Can I …? ruxsat, Could you …? suhbatdoshning yordam amali. Please odobni kuchaytiradi, lekin ohang ham muhim.","hint":"You should … / Could you …, please? / Would you mind + -ing?"},{"id":"en-a2-10-exit3","type":"choice","skill":"grammar","prompt":"Could you bu yerda albatta o‘tmishmi?","answers":["No"],"explanation":"Could muloyimlikni ham ifodalaydi.","hint":"You should … / Could you …, please? / Would you mind + -ing?","options":["No","Yes","Always"]},{"id":"en-a2-10-exit4","type":"choice","skill":"grammar","prompt":"Should dan keyin shakl?","answers":["base verb"],"explanation":"Should take.","hint":"You should … / Could you …, please? / Would you mind + -ing?","options":["base verb","verb + s","to + verb"]}],[{"id":"en-a2-10-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["You shouldn’t study all night."],"explanation":"Should + asosiy fe’l maslahat: You should rest. Shouldn’t qilmaslik tavsiyasi. Bu har doim majburiy qoida emas. Could you …? va Would you …? kundalik odobli so‘rov. Could bu yerda o‘tgan zamon haqida emas. Can I …? ruxsat, Could you …? suhbatdoshning yordam amali. Please odobni kuchaytiradi, lekin ohang ham muhim.","hint":"You should … / Could you …, please? / Would you mind + -ing?","tokens":["You","shouldn’t","study","all","night."]},{"id":"en-a2-10-exit-b1","type":"grammarFill","skill":"grammar","prompt":"Could you ___ me?","answers":["help"],"explanation":"Should + asosiy fe’l maslahat: You should rest. Shouldn’t qilmaslik tavsiyasi. Bu har doim majburiy qoida emas. Could you …? va Would you …? kundalik odobli so‘rov. Could bu yerda o‘tgan zamon haqida emas. Can I …? ruxsat, Could you …? suhbatdoshning yordam amali. Please odobni kuchaytiradi, lekin ohang ham muhim.","hint":"You should … / Could you …, please? / Would you mind + -ing?"},{"id":"en-a2-10-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Can I borrow your dictionary?"],"explanation":"Should + asosiy fe’l maslahat: You should rest. Shouldn’t qilmaslik tavsiyasi. Bu har doim majburiy qoida emas. Could you …? va Would you …? kundalik odobli so‘rov. Could bu yerda o‘tgan zamon haqida emas. Can I …? ruxsat, Could you …? suhbatdoshning yordam amali. Please odobni kuchaytiradi, lekin ohang ham muhim.","hint":"You should … / Could you …, please? / Would you mind + -ing?","tokens":["Can","I","borrow","your","dictionary?"]},{"id":"en-a2-10-exit-b3","type":"choice","skill":"grammar","prompt":"Could you bu yerda albatta o‘tmishmi?","answers":["No"],"explanation":"Could muloyimlikni ham ifodalaydi.","hint":"You should … / Could you …, please? / Would you mind + -ing?","options":["No","Yes","Always"]},{"id":"en-a2-10-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["You should drink some water."],"explanation":"Should + asosiy fe’l maslahat: You should rest. Shouldn’t qilmaslik tavsiyasi. Bu har doim majburiy qoida emas. Could you …? va Would you …? kundalik odobli so‘rov. Could bu yerda o‘tgan zamon haqida emas. Can I …? ruxsat, Could you …? suhbatdoshning yordam amali. Please odobni kuchaytiradi, lekin ohang ham muhim.","hint":"You should … / Could you …, please? / Would you mind + -ing?","tokens":["You","should","drink","some","water."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-a2-10","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-a2-10","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-a2-10","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-a2-10","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-a2-10","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-a2-10","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-a2-10","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-a2-10","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a2-11','en-a2-11',null,2,11,'published',1,'{"id":"en-a2-11","baseId":"en-a2-11","revision":1,"level":"A2","levelIndex":2,"order":11,"title":"Present Perfect: tajriba va hozirgi natija","objective":"Aniq tugallangan vaqt aytilmaganda tajriba yoki natijani ifodalaysiz.","context":"Sinf ko‘rgazma uchun qilingan ishlarni tekshiradi.","prerequisites":["en-a2-10"],"minutes":40,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Have/has + past participle: I have finished, she has seen. Noto‘g‘ri fe’lning uchinchi shakli har doim ikkinchi bilan bir xil emas: went → gone.","Present Perfect o‘tmish bilan hozir o‘rtasidagi aloqani ko‘rsatadi. I have lost my key — hozir kalit yo‘q.","Yesterday kabi tugallangan vaqt aniq bo‘lsa Past Simple: I lost it yesterday. Present Perfect uchun faqat signal so‘zga emas, ma’noga tayaning."],"pattern":"have/has + V3; have finished / has seen","examples":["I have finished the poster.","She has seen this film.","We have visited Bukhara.","He has lost his key.","Have you tried this activity?","They haven’t started yet."],"vocabulary":[{"id":"en-a2-11-v0","term":"finish","meaning":"tugatmoq","ipa":"/ˈfɪnɪʃ/","collocation":"finish a poster","example":"I have finished the poster."},{"id":"en-a2-11-v1","term":"lose","meaning":"yo‘qotmoq","ipa":"/luːz/","collocation":"lose a key","example":"lose a key"},{"id":"en-a2-11-v2","term":"try","meaning":"sinab ko‘rmoq","ipa":"/traɪ/","collocation":"try an activity","example":"try an activity"},{"id":"en-a2-11-v3","term":"key","meaning":"kalit","ipa":"/kiː/","collocation":"a house key","example":"He has lost his key."}],"visuals":[{"kind":"timeline","title":"Ma’no va tuzilish","items":["have/has + V3; have finished / has seen","I have finished the poster.","She has seen this film."],"timeline":[{"why":"Have finished: tugagan harakatning hozirgi natijasi muhim. Aniq tugagan vaqt berilmagan.","events":[{"kind":"point","x":205,"label":"Plakat tugagan"},{"kind":"link","from":205,"to":320,"label":"Hozir natija bor"}]},{"why":"Has seen tajribani hozirgacha bo‘lgan davrga bog‘laydi. Film ko‘rilgan sana aytilmagan.","events":[{"kind":"point","x":180,"label":"Oldingi tajriba"},{"kind":"link","from":180,"to":320,"label":"Hozirgacha bo‘lgan tajriba"}]}]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Sinf ko‘rgazma uchun qilingan ishlarni tekshiradi.","We have visited Bukhara.","Have you tried this activity?"]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"He has lost his key.","audio":"/english-course/v7.23/en-a2-11-dictation.mp3"},"exercises":[{"id":"en-a2-11-choice","type":"choice","skill":"grammar","prompt":"Hozirgi natijani tanlang.","answers":["I have lost my key, so I can’t open the door."],"explanation":"Have + lost hozirgi muammo bilan bog‘langan.","hint":"have/has + V3; have finished / has seen","options":["I have lost my key, so I can’t open the door.","I have lose my key.","I have lost yesterday my key (finished time)."]},{"id":"en-a2-11-gap","type":"grammarFill","skill":"grammar","prompt":"She ___ seen this film.","answers":["has"],"explanation":"Have/has + past participle: I have finished, she has seen. Noto‘g‘ri fe’lning uchinchi shakli har doim ikkinchi bilan bir xil emas: went → gone. Present Perfect o‘tmish bilan hozir o‘rtasidagi aloqani ko‘rsatadi. I have lost my key — hozir kalit yo‘q. Yesterday kabi tugallangan vaqt aniq bo‘lsa Past Simple: I lost it yesterday. Present Perfect uchun faqat signal so‘zga emas, ma’noga tayaning.","hint":"have/has + V3; have finished / has seen"},{"id":"en-a2-11-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["I have finished the poster."],"explanation":"Have/has + past participle: I have finished, she has seen. Noto‘g‘ri fe’lning uchinchi shakli har doim ikkinchi bilan bir xil emas: went → gone. Present Perfect o‘tmish bilan hozir o‘rtasidagi aloqani ko‘rsatadi. I have lost my key — hozir kalit yo‘q. Yesterday kabi tugallangan vaqt aniq bo‘lsa Past Simple: I lost it yesterday. Present Perfect uchun faqat signal so‘zga emas, ma’noga tayaning.","hint":"have/has + V3; have finished / has seen","tokens":["I","have","finished","the","poster."]},{"id":"en-a2-11-fix","type":"correction","skill":"grammar","prompt":"I have went there.","answers":["I have gone there."],"explanation":"Have/has + past participle: I have finished, she has seen. Noto‘g‘ri fe’lning uchinchi shakli har doim ikkinchi bilan bir xil emas: went → gone. Present Perfect o‘tmish bilan hozir o‘rtasidagi aloqani ko‘rsatadi. I have lost my key — hozir kalit yo‘q. Yesterday kabi tugallangan vaqt aniq bo‘lsa Past Simple: I lost it yesterday. Present Perfect uchun faqat signal so‘zga emas, ma’noga tayaning.","hint":"have/has + V3; have finished / has seen"},{"id":"en-a2-11-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["tugatmoq","yo‘qotmoq","sinab ko‘rmoq","kalit"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"have/has + V3; have finished / has seen","left":["finish","lose","try","key"],"options":["tugatmoq","yo‘qotmoq","sinab ko‘rmoq","kalit"]}],"reading":{"title":"Present Perfect: tajriba va hozirgi natija — vaziyat","text":"Our class has prepared a small exhibition. I have finished the poster, and Lola has chosen the pictures. Ali has visited Bukhara, so he can explain one photo of the city. We haven’t put the labels on the wall yet. The teacher asks if we have checked all the names. I have lost my pencil, so I need to borrow one now. We finished the largest picture yesterday, but there is still work to do today.","sentences":["Our class has prepared a small exhibition.","I have finished the poster, and Lola has chosen the pictures.","Ali has visited Bukhara, so he can explain one photo of the city.","We haven’t put the labels on the wall yet.","The teacher asks if we have checked all the names.","I have lost my pencil, so I need to borrow one now.","We finished the largest picture yesterday, but there is still work to do today."],"questions":[{"id":"en-a2-11-reading0","type":"choice","skill":"reading","prompt":"Nima hali qilinmagan?","answers":["putting labels on the wall"],"explanation":"Haven’t put labels … yet.","hint":"have/has + V3; have finished / has seen","options":["putting labels on the wall","choosing pictures","finishing the poster"]},{"id":"en-a2-11-reading1","type":"choice","skill":"reading","prompt":"Ali nima uchun rasmni tushuntira oladi?","answers":["he has visited Bukhara"],"explanation":"Visited Bukhara tajribasi bor.","hint":"have/has + V3; have finished / has seen","options":["he has visited Bukhara","he painted it yesterday","he has a key"]},{"id":"en-a2-11-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"have/has + V3; have finished / has seen","options":["Our class has prepared a small exhibition.","I have finished the poster, and Lola has chosen the pictures.","Ali has visited Bukhara, so he can explain one photo of the city.","We haven’t put the labels on the wall yet.","The teacher asks if we have checked all the names.","I have lost my pencil, so I need to borrow one now.","We finished the largest picture yesterday, but there is still work to do today."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"I have finished the poster. Lola has chosen the pictures. Ali has visited Bukhara. We haven’t put the labels on the wall yet. Have you checked all the names?","audio":"/english-course/v7.23/en-a2-11.mp3","synthetic":true,"questions":[{"id":"en-a2-11-listening0","type":"choice","skill":"listening","prompt":"Rasmlarni kim tanlagan?","answers":["Lola"],"explanation":"Lola has chosen.","hint":"have/has + V3; have finished / has seen","options":["Lola","Ali","the guide"]},{"id":"en-a2-11-listening1","type":"choice","skill":"listening","prompt":"Yorliqlar devordami?","answers":["not yet"],"explanation":"Haven’t … yet.","hint":"have/has + V3; have finished / has seen","options":["not yet","all of them","since Monday"]},{"id":"en-a2-11-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["poster","Bukhara"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"have/has + V3; have finished / has seen","rows":["Tayyor ish","Ali ko‘rgan shahar"]},{"id":"en-a2-11-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["He has lost his key."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"have/has + V3; have finished / has seen","audio":"/english-course/v7.23/en-a2-11-dictation.mp3","transcript":"He has lost his key."}]},"writing":{"task":"Loyiha uchun allaqachon qilingan va hali qilinmagan ishlarni yozing.","audience":"Sinfdagi sherigingiz","minWords":55,"maxWords":140,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"We have prepared most of our exhibition. I have finished the main poster, and my friend has chosen three photos. We have checked the city names, but we haven’t written all the labels yet. Ali has visited the place in one photo, so he can explain it. We need to finish the labels before Friday.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["I have finished the poster.","She has seen this film.","We have visited Bukhara."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Have you ever …? bilan ikki tajribani so‘rang; natijani misol bilan tushuntiring.","seconds":50,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Loyiha uchun allaqachon qilingan va hali qilinmagan ishlarni yozing.","exit":[[{"id":"en-a2-11-exit0","type":"grammarFill","skill":"grammar","prompt":"I ___ finished.","answers":["have"],"explanation":"Have/has + past participle: I have finished, she has seen. Noto‘g‘ri fe’lning uchinchi shakli har doim ikkinchi bilan bir xil emas: went → gone. Present Perfect o‘tmish bilan hozir o‘rtasidagi aloqani ko‘rsatadi. I have lost my key — hozir kalit yo‘q. Yesterday kabi tugallangan vaqt aniq bo‘lsa Past Simple: I lost it yesterday. Present Perfect uchun faqat signal so‘zga emas, ma’noga tayaning.","hint":"have/has + V3; have finished / has seen"},{"id":"en-a2-11-exit1","type":"grammarFill","skill":"grammar","prompt":"She has ___ it. (see)","answers":["seen"],"explanation":"Have/has + past participle: I have finished, she has seen. Noto‘g‘ri fe’lning uchinchi shakli har doim ikkinchi bilan bir xil emas: went → gone. Present Perfect o‘tmish bilan hozir o‘rtasidagi aloqani ko‘rsatadi. I have lost my key — hozir kalit yo‘q. Yesterday kabi tugallangan vaqt aniq bo‘lsa Past Simple: I lost it yesterday. Present Perfect uchun faqat signal so‘zga emas, ma’noga tayaning.","hint":"have/has + V3; have finished / has seen"},{"id":"en-a2-11-exi